#!/usr/bin/env python3
"""Short regression runs for benchmark output; not a performance evaluation. Generated by ChatGPT"""
import argparse
import json
import math
import os
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]


def require(condition, message):
    if not condition:
        raise AssertionError(message)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--build-dir', type=Path, default=ROOT / 'build')
    args = parser.parse_args()
    build = args.build_dir.resolve()
    program = build / 'benchmark'
    base = os.environ.copy()
    base.pop('LD_PRELOAD', None)
    base.pop('ALLOC_STRATEGY', None)

    def invoke(arguments, library=None, strategy=None, success=True):
        environment = base.copy()
        if library:
            environment['LD_PRELOAD'] = str(build / library)
        if strategy is not None:
            environment['ALLOC_STRATEGY'] = strategy
        result = subprocess.run([str(program), *arguments], env=environment,
                                capture_output=True, text=True, timeout=30)
        if success:
            require(result.returncode == 0,
                    f'{arguments}: {result.stdout}{result.stderr}')
            require(len(result.stdout.splitlines()) == 1, 'expected exactly one JSON line')
            return json.loads(result.stdout)
        require(result.returncode != 0, f'invalid invocation succeeded: {arguments}')
        require(not result.stdout, 'failed benchmark published a result')
        require('benchmark:' in result.stderr or 'Usage:' in result.stderr,
                'failed invocation has no explanation')
        return None

    configurations = [('glibc', 'system', None)]
    configurations += [(variant, strategy, library)
                       for variant, library in (('plain', 'liballocator.so'),
                                                ('stats', 'liballocator_with_stats.so'))
                       for strategy in ('first', 'best', 'next')]
    runs = 0
    for workload in ('uniform', 'mixed', 'fragmented', 'resize'):
        for seed in (1234567, 4294967295):
            reference = None
            for variant, strategy, library in configurations:
                steps = 10000
                row = invoke([workload, str(seed), str(steps), strategy], library, strategy)
                require(row['schema_version'] == 1, 'unknown output schema')
                require(row['workload'] == workload and row['seed'] == seed, 'wrong trace identity')
                require(row['variant'] == variant and row['allocator'] == strategy, 'wrong allocator')
                require(Path(row['allocator_library']).name == (library or 'libc.so.6'),
                        'reported provider is incorrect')
                operations = row['operations']
                expected_calls = steps + (1536 if workload == 'fragmented' else 0)
                require(operations['total'] == expected_calls, 'wrong timed API call count')
                require(operations['total'] == sum(operations[k] for k in
                        ('malloc', 'calloc', 'realloc', 'free')), 'operation counts disagree')
                require(row['peak_live_requested_bytes'] >= row['live_requested_bytes'],
                        'live requested bytes exceed their peak')
                require(0 <= row['cleanup_free_calls'] <= 1024, 'invalid cleanup count')
                require(row['elapsed_ns'] >= 0, 'negative duration')
                throughput = row['throughput_calls_per_second']
                if row['elapsed_ns']:
                    require(math.isclose(throughput, expected_calls * 1e9 / row['elapsed_ns']),
                            'incorrect throughput')
                else:
                    require(throughput is None, 'zero-duration throughput must be null')

                points = row['checkpoints']
                for point in points.values():
                    require(point['rss_kib'] > 0 and point['peak_rss_kib'] >= 0,
                            'invalid memory measurement')
                    stats = point['allocator_stats']
                    if variant != 'stats':
                        require(stats is None, 'unavailable diagnostics must be null')
                        continue
                    require(stats['mapped_bytes'] >= stats['capacity_bytes'] + stats['free_bytes'],
                            'negative metadata footprint')
                    require(stats['peak_mapped_bytes'] >= stats['mapped_bytes'], 'invalid mapped peak')
                    expected_average = stats['free_bytes'] / stats['free_blocks'] if stats['free_blocks'] else 0
                    require(math.isclose(stats['average_free_block_size'], expected_average),
                            'incorrect average free block size')

                if variant == 'stats':
                    initial = points['initial']['allocator_stats']
                    before = points['before_cleanup']['allocator_stats']
                    after = points['after_cleanup']['allocator_stats']
                    for operation in ('malloc', 'calloc', 'realloc', 'free'):
                        field = operation + '_calls'
                        require(before[field] - initial[field] == operations[operation],
                                f'workload/allocator {field} disagree')
                    require(before['requested_bytes'] - initial['requested_bytes'] ==
                            row['live_requested_bytes'], 'incorrect live requested accounting')
                    for field in ('live_blocks', 'requested_bytes', 'capacity_bytes'):
                        require(after[field] == initial[field], f'cleanup leaked {field}')
                    require(after['free_calls'] - before['free_calls'] == row['cleanup_free_calls'],
                            'cleanup call count disagrees')

                signature = (operations, row['live_requested_bytes'], row['peak_live_requested_bytes'],
                             row['checksum'], row['cleanup_free_calls'])
                if reference is not None:
                    require(signature == reference, 'allocators received different work or data')
                reference = signature
                runs += 1
        print(f'PASS: {workload}: paired traces across all allocator variants', flush=True)

    # Scaling preserves the request sequence, including fragmented setup, while
    # multiplying live payload totals. Every provider must produce the same checksum.
    for workload in ('uniform', 'mixed', 'fragmented', 'resize'):
        baseline = invoke([workload, '12345', '1000'])
        require(baseline['size_scale'] == 1, 'incorrect default scale')
        for scale in (1, 16):
            checksum = None
            for variant, strategy, library in configurations:
                row = invoke([workload, '12345', '1000', strategy,
                              '--size-scale', str(scale)], library, strategy)
                require(row['size_scale'] == scale, 'scale not reported')
                require(row['operations'] == baseline['operations'], 'scaling changed operations')
                for field in ('live_requested_bytes', 'peak_live_requested_bytes'):
                    require(row[field] == baseline[field] * scale, f'{field} not scaled')
                if checksum is not None:
                    require(row['checksum'] == checksum, 'scaled checksums differ')
                checksum = row['checksum']
                if scale == 1:
                    require(checksum == baseline['checksum'], 'explicit scale 1 changed trace')
    for value in ('0', '-1', '1.5', 'abc', '18446744073709551615',
                  '18446744073709551616'):
        invoke(['mixed', '1', '1', '--size-scale', value], success=False)
    invoke(['uniform', '1', '1', '--size-scale'], success=False)
    invoke(['uniform', '1', '1', '--size-scale', '1', '--size-scale', '2'], success=False)
    print('PASS: size scaling, unchanged traces, and invalid/overflowing scales', flush=True)

    # Small runs and optional labels also produce complete results.
    for workload in ('uniform', 'mixed', 'fragmented', 'resize'):
        row = invoke([workload, '1', '1'])
        require(row['steps'] == 1 and row['allocator'] == 'system', 'short/default invocation failed')
    row = invoke(['uniform', '1', '1'], strategy='best')
    require(row['allocator'] == 'system', 'environment setting mislabeled glibc')
    for variant, library in (('plain', 'liballocator.so'), ('stats', 'liballocator_with_stats.so')):
        row = invoke(['uniform', '1', '1', 'first'], library, 'invalid')
        require(row['variant'] == variant and row['allocator'] == 'first', 'fallback mismatch')

    invalid = [[], ['other', '1', '10'], ['uniform', '0', '10'],
               ['uniform', '-1', '10'], ['uniform', '+1', '10'], ['uniform', ' 1', '10'],
               ['uniform', '4294967296', '10'], ['uniform', 'abc', '10'],
               ['uniform', '1x', '10'], ['uniform', '1', '0'], ['uniform', '1', '-1'],
               ['uniform', '1', '18446744073709551615'],
               ['uniform', '1', '18446744073709551616'], ['uniform', '1', '10x'],
               ['uniform', '1', '10', 'unknown'], ['uniform', '1', '10', 'first']]
    for arguments in invalid:
        invoke(arguments, success=False)
    invoke(['uniform', '1', '10', 'best'], 'liballocator.so', 'next', success=False)
    invoke(['uniform', '1', '10', 'system'], 'liballocator_with_stats.so', 'first', success=False)
    invoke(['uniform', '1', '10'], 'liballocator.so:' + str(build / 'liballocator_with_stats.so'),
           'first', success=False)
    help_result = subprocess.run([str(program), '--help'], env=base, capture_output=True,
                                 text=True, timeout=10)
    require(help_result.returncode == 0 and 'Usage:' in help_result.stdout, 'help failed')
    print(f'PASS: {runs} matched runs; short runs, fallback, CLI and preload checks', flush=True)


if __name__ == '__main__':
    main()
